import{_ as e,o,c as i,a2 as t}from"./chunks/framework.CgxQ0r6v.js";const m=JSON.parse('{"title":"Manual de Estudio Profundo: Evaluación 3","description":"","frontmatter":{},"headers":[],"relativePath":"materias/Proyecto_Sociotecnologico_I/documentacion/I-II/Lectura_Catedra_Evaluacion_3.md","filePath":"materias/Proyecto_Sociotecnologico_I/documentacion/I-II/Lectura_Catedra_Evaluacion_3.md"}'),r={name:"materias/Proyecto_Sociotecnologico_I/documentacion/I-II/Lectura_Catedra_Evaluacion_3.md"};function s(c,a,l,n,d,u){return o(),i("div",null,[...a[0]||(a[0]=[t('<h1 id="manual-de-estudio-profundo-evaluacion-3" tabindex="-1">Manual de Estudio Profundo: Evaluación 3 <a class="header-anchor" href="#manual-de-estudio-profundo-evaluacion-3" aria-label="Permalink to &quot;Manual de Estudio Profundo: Evaluación 3&quot;">​</a></h1><h2 id="materia-proyecto-sociotecnologico-trayecto-i" tabindex="-1">Materia: Proyecto Sociotecnológico (Trayecto I) <a class="header-anchor" href="#materia-proyecto-sociotecnologico-trayecto-i" aria-label="Permalink to &quot;Materia: Proyecto Sociotecnológico (Trayecto I)&quot;">​</a></h2><h3 id="eje-tematico-planificacion-de-actividades-y-recursos" tabindex="-1">Eje Temático: Planificación de Actividades y Recursos <a class="header-anchor" href="#eje-tematico-planificacion-de-actividades-y-recursos" aria-label="Permalink to &quot;Eje Temático: Planificación de Actividades y Recursos&quot;">​</a></h3><hr><h2 id="🧭-introduccion-de-la-teoria-a-la-logistica" tabindex="-1">🧭 Introducción: De la Teoría a la Logística <a class="header-anchor" href="#🧭-introduccion-de-la-teoria-a-la-logistica" aria-label="Permalink to &quot;🧭 Introducción: De la Teoría a la Logística&quot;">​</a></h2><p>Gracias a la Estructura Analítica del Proyecto (EAP), ya sabes <em>exactamente</em> cuáles son las actividades técnicas y sociales que debes realizar en la comunidad. Sin embargo, no puedes simplemente llegar un martes por la mañana y empezar a desarmar computadoras. Todo ingeniero sabe que la improvisación es la madre del fracaso operativo.</p><p>En esta fase, convertiremos esas actividades abstractas en una <strong>matriz logística</strong>. Planificar es anticiparse al futuro: saber qué se va a hacer, quién lo va a hacer y qué herramientas se necesitan.</p><hr><h2 id="🏛️-capitulo-i-identificacion-de-actividades" tabindex="-1">🏛️ CAPÍTULO I: Identificación de Actividades <a class="header-anchor" href="#🏛️-capitulo-i-identificacion-de-actividades" aria-label="Permalink to &quot;🏛️ CAPÍTULO I: Identificación de Actividades&quot;">​</a></h2><p>El Trayecto I en el PNFI se enfoca en la línea de <strong>Informática Aplicada</strong>. Específicamente, tus proyectos gravitarán hacia el Soporte Técnico a Usuarios y Equipos.</p><p>Las actividades no deben ser vagas (&quot;arreglar PCs&quot;). Deben ser específicas, secuenciales y comprobables.</p><h3 id="_1-1-actividades-de-soporte-tecnico-hardware-y-software" tabindex="-1">1.1 Actividades de Soporte Técnico (Hardware y Software) <a class="header-anchor" href="#_1-1-actividades-de-soporte-tecnico-hardware-y-software" aria-label="Permalink to &quot;1.1 Actividades de Soporte Técnico (Hardware y Software)&quot;">​</a></h3><p>Ejemplos de tareas correctamente definidas:</p><ul><li>Realizar inventario técnico del hardware existente en el laboratorio.</li><li>Ejecutar limpieza física profunda (soplado, contactos) de las tarjetas madre.</li><li>Formatear e instalar el sistema operativo Canaima GNU/Linux en 5 estaciones de trabajo.</li><li>Configurar la conexión en red local (LAN) de los equipos operativos.</li></ul><h3 id="_1-2-actividades-de-soporte-a-usuarios-alfabetizacion" tabindex="-1">1.2 Actividades de Soporte a Usuarios (Alfabetización) <a class="header-anchor" href="#_1-2-actividades-de-soporte-a-usuarios-alfabetizacion" aria-label="Permalink to &quot;1.2 Actividades de Soporte a Usuarios (Alfabetización)&quot;">​</a></h3><p>El impacto social es obligatorio. Ejemplos de tareas:</p><ul><li>Diseñar el material didáctico (guías rápidas) sobre el uso de procesadores de texto.</li><li>Dictar taller formativo de 4 horas dirigido al personal administrativo.</li></ul><hr><h2 id="🧩-capitulo-ii-determinacion-de-recursos" tabindex="-1">🧩 CAPÍTULO II: Determinación de Recursos <a class="header-anchor" href="#🧩-capitulo-ii-determinacion-de-recursos" aria-label="Permalink to &quot;🧩 CAPÍTULO II: Determinación de Recursos&quot;">​</a></h2><p>Una actividad no se ejecuta sola. Por cada tarea que listaste en el capítulo anterior, debes definir explícitamente los recursos que vas a consumir. Si olvidas planificar un recurso, la actividad se detendrá el día de la ejecución.</p><p>Los recursos se dividen en tres grandes categorías:</p><h3 id="_2-1-recursos-materiales-y-tecnicos" tabindex="-1">2.1 Recursos Materiales y Técnicos <a class="header-anchor" href="#_2-1-recursos-materiales-y-tecnicos" aria-label="Permalink to &quot;2.1 Recursos Materiales y Técnicos&quot;">​</a></h3><p>Es todo lo tangible y tecnológico que necesitas para ejecutar la tarea.</p><ul><li><em>Para limpiar equipos:</em> Brochas, sopladoras, limpia contactos, destornilladores, pasta térmica, paños antiestáticos.</li><li><em>Para instalar software:</em> Pendrives booteables, cables de red, switch, router.</li><li><em>Para el taller:</em> Video beam, pizarra magnética, marcadores, refrigerios.</li></ul><h3 id="_2-2-recursos-humanos" tabindex="-1">2.2 Recursos Humanos <a class="header-anchor" href="#_2-2-recursos-humanos" aria-label="Permalink to &quot;2.2 Recursos Humanos&quot;">​</a></h3><p>¿Quién va a ejecutar la tarea?</p><ul><li>Los <strong>Estudiantes Investigadores</strong> (Ustedes, el equipo de proyecto).</li><li>Los <strong>Tutores</strong> (Técnico y Académico) que supervisarán el taller.</li><li>El <strong>Personal de la comunidad</strong> (El director que debe abrirles la puerta del liceo un sábado).</li></ul><h3 id="_2-3-recursos-institucionales-logisticos" tabindex="-1">2.3 Recursos Institucionales / Logísticos <a class="header-anchor" href="#_2-3-recursos-institucionales-logisticos" aria-label="Permalink to &quot;2.3 Recursos Institucionales / Logísticos&quot;">​</a></h3><p>Abarca el transporte (¿cómo van a llevar las herramientas a la comunidad?), el espacio físico (¿qué salón usarán para el taller?) y los permisos.</p><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p><strong>La Matriz de Planificación</strong> La forma más profesional de presentar esto en tu Informe de Proyecto es mediante una tabla.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Actividad</th><th style="text-align:left;">Recursos Materiales</th><th style="text-align:left;">Recursos Humanos</th><th style="text-align:left;">Responsable Directo</th></tr></thead><tbody><tr><td style="text-align:left;">Limpieza de hardware</td><td style="text-align:left;">Sopladoras, brochas, destornilladores</td><td style="text-align:left;">Estudiantes</td><td style="text-align:left;">Juan Pérez (Estudiante)</td></tr></tbody></table></div><p>Con las actividades definidas y los recursos calculados, estamos listos para ponerle precio y fecha a nuestro proyecto en el próximo capítulo: El Presupuesto y el Cronograma.</p>',31)])])}const h=e(r,[["render",s]]);export{m as __pageData,h as default};
